CREATE TABLE IF NOT EXISTS candidate_mailboxes(id text PRIMARY KEY,candidate_id text NOT NULL,provider text NOT NULL,email_address text NOT NULL,connection_type text NOT NULL,monitoring_enabled boolean NOT NULL DEFAULT false,connection_status text NOT NULL DEFAULT 'PENDING',credential_ciphertext text,last_sync_attempt_at timestamptz,last_successful_sync_at timestamptz,next_sync_at timestamptz,sync_cursor text,provider_history_id text,failed_sync_count integer NOT NULL DEFAULT 0,last_error_code text,last_error_message text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(candidate_id,provider));
CREATE TABLE IF NOT EXISTS mailbox_messages(id text PRIMARY KEY,mailbox_id text NOT NULL REFERENCES candidate_mailboxes(id) ON DELETE CASCADE,candidate_id text NOT NULL,provider_message_id text NOT NULL,provider_thread_id text,sender_name text,sender_email text,recipient_email text,subject text,sent_at timestamptz,message_hash text,body_hash text,recruitment_relevance_score double precision,processing_status text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(mailbox_id,provider_message_id));
CREATE TABLE IF NOT EXISTS mailbox_attachments(id text PRIMARY KEY,mailbox_message_id text NOT NULL REFERENCES mailbox_messages(id) ON DELETE CASCADE,filename text,mime_type text,size bigint,checksum text,attachment_type text,extraction_status text,extracted_text_reference text,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(mailbox_message_id,checksum));
CREATE TABLE IF NOT EXISTS mailbox_attachment_cache(checksum text PRIMARY KEY,mime_type text,size bigint,extracted_text text,extraction_method text,attachment_type text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS ai_recruitment_events(id text PRIMARY KEY,candidate_id text NOT NULL,mailbox_message_id text REFERENCES mailbox_messages(id),primary_status text NOT NULL,confidence double precision NOT NULL,company_name text,company_domain text,job_title text,recruiter_name text,recruiter_email text,interview_date date,interview_time time,interview_mode text,offered_ctc numeric,currency text,joining_date date,offer_date date,offer_expiry_date date,structured_result jsonb NOT NULL,summary text,requires_manual_review boolean NOT NULL DEFAULT true,review_status text NOT NULL DEFAULT 'PENDING',reviewed_by text,reviewed_at timestamptz,review_notes text,ai_model text,prompt_name text,prompt_version text,schema_version text,processing_duration_ms integer,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(mailbox_message_id));
CREATE TABLE IF NOT EXISTS candidate_status_history(id text PRIMARY KEY,candidate_id text NOT NULL,previous_detected_status text,new_detected_status text,confirmed_status text,source_type text,source_id text,confidence double precision,reviewed_by text,reviewed_at timestamptz,review_notes text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS offer_verification_cases(id text PRIMARY KEY,candidate_id text NOT NULL,ai_recruitment_event_id text NOT NULL REFERENCES ai_recruitment_events(id),company_name text,job_title text,offered_ctc numeric,currency text,offer_date date,joining_date date,offer_expiry_date date,verification_status text NOT NULL,confidence double precision,reviewed_by text,reviewed_at timestamptz,notes text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(ai_recruitment_event_id));
CREATE TABLE IF NOT EXISTS mailbox_sync_jobs(id text PRIMARY KEY,mailbox_id text NOT NULL REFERENCES candidate_mailboxes(id) ON DELETE CASCADE,status text NOT NULL,scheduled_for timestamptz NOT NULL DEFAULT now(),requested_by text,attempts integer NOT NULL DEFAULT 0,started_at timestamptz,completed_at timestamptz,messages_fetched integer DEFAULT 0,messages_processed integer DEFAULT 0,events_detected integer DEFAULT 0,error_code text,error_message text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS recruitment_audit_log(id text PRIMARY KEY,actor text,role text,action text NOT NULL,candidate_id text,source_id text,previous_value jsonb,new_value jsonb,source_ip text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS recruitment_review_flags(id text PRIMARY KEY,candidate_id text NOT NULL,event_id text,flag_type text NOT NULL,severity text NOT NULL DEFAULT 'MEDIUM',details jsonb NOT NULL DEFAULT '{}'::jsonb,review_status text NOT NULL DEFAULT 'PENDING',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(candidate_id,event_id,flag_type));
CREATE INDEX IF NOT EXISTS idx_mailbox_monitoring ON candidate_mailboxes(monitoring_enabled,next_sync_at);
CREATE INDEX IF NOT EXISTS idx_mail_jobs_queue ON mailbox_sync_jobs(status,scheduled_for);
CREATE INDEX IF NOT EXISTS idx_recruitment_events_review ON ai_recruitment_events(review_status,created_at DESC);
CREATE INDEX IF NOT EXISTS idx_recruitment_events_candidate ON ai_recruitment_events(candidate_id,created_at DESC);
CREATE INDEX IF NOT EXISTS idx_offer_cases_status ON offer_verification_cases(verification_status,created_at DESC);
CREATE INDEX IF NOT EXISTS idx_recruitment_flags_review ON recruitment_review_flags(review_status,created_at DESC);
